from rules import SOLVERS


def solve(data):
    return {component_id: solver(data[component_id])
            for component_id, solver in SOLVERS.items()}

from itertools import product, combinations
import heapq


def _rounded(numerator, denominator, mode):
    if mode == "half_up":
        return (numerator + denominator // 2) // denominator
    return numerator // denominator


def _ledger(data, sequence_first, discounted):
    cutoff = data.get("cutoff", 10**9)
    chosen = {}
    for pos, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        key = ((sequence, event.get("revision", 0), pos) if sequence_first
               else (event.get("revision", 0), pos))
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]
    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = _rounded(raw * (10000 - discount), 10000, mode)
        base = net if discounted else raw
        tax = _rounded(base * event.get("tax_bp", 0), 10000, mode)
        amount = net + tax
        if event.get("kind") == "refund":
            amount = -amount
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def _build_ledger(sequence_first, discounted):
    return lambda data: _ledger(data, sequence_first, discounted)


def _dependency_solver(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    choices = []
    for name in names:
        versions = sorted(row["version"] for row in packages[name]
                          if row["version"] not in blocked.get(name, [])
                          and (name not in pins or row["version"] == pins[name]))
        choices.append([-1] + versions)

    best_key = None
    best_versions = None
    for values in product(*choices):
        selected = {name: value for name, value in zip(names, values) if value != -1}
        rows = {name: {row["version"]: row for row in packages[name]}
                for name in names}
        edges = {}
        closure = set()
        pending = []
        valid = True
        for name, bounds in data["roots"].items():
            version = selected.get(name)
            if version is None or not bounds[0] <= version <= bounds[1]:
                valid = False
                break
            pending.append(name)
        if not valid:
            continue

        while pending and valid:
            name = pending.pop()
            if name in closure:
                continue
            closure.add(name)
            version = selected.get(name)
            if version is None:
                valid = False
                break
            row = rows[name][version]
            deps = [dep for dep in row.get("deps", [])
                    if not dep.get("feature") or dep["feature"] in features]
            edges[name] = []
            for dep in deps:
                other = dep["name"]
                other_version = selected.get(other)
                if (other_version is None or
                        not dep["min"] <= other_version <= dep["max"]):
                    valid = False
                    break
                edges[name].append(other)
                pending.append(other)

        if not valid or closure != set(selected):
            continue

        finished, active = set(), set()
        def acyclic(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            if any(not acyclic(other) for other in edges.get(name, [])):
                return False
            active.remove(name)
            finished.add(name)
            return True

        if not all(acyclic(name) for name in closure):
            continue
        key = tuple(selected.get(name, -1) for name in names)
        if best_key is None or key < best_key:
            best_key = key
            best_versions = selected

    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}


def _quota_intervals(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    options = [job for job in jobs if job["id"] not in blocked]
    best_value = None
    best_ids = None

    for subset in combinations(options, k):
        ids = {job["id"] for job in subset}
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in subset:
            group = job["group"]
            counts[group] = counts.get(group, 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ordered = sorted(subset, key=lambda job: (job["start"], job["end"]))
        if any(ordered[i - 1]["end"] > ordered[i]["start"]
               for i in range(1, len(ordered))):
            continue
        value = sum(job["value"] for job in subset)
        selected_ids = sorted(ids)
        if (best_value is None or value > best_value or
                (value == best_value and selected_ids < best_ids)):
            best_value, best_ids = value, selected_ids

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def _temporal_routes(data):
    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    source = data["source"]
    initial_mask = bit.get(source, 0)
    coupons = data["coupons"]
    start = data["start"]
    initial = (source, 0, initial_mask)
    distance = {initial: start}
    queue = [(start, source, 0, initial_mask)]

    while queue:
        time, node, used, mask = heapq.heappop(queue)
        state = (node, used, mask)
        if distance.get(state) != time:
            continue
        if node == data["target"] and used == coupons and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            next_mask = mask | bit.get(edge["v"], 0)
            options = [(edge["duration"], used)]
            if used < coupons:
                duration = max(2, edge["duration"] - edge.get("discount", 0))
                options.append((duration, used + 1))
            for duration, next_used in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_state = (edge["v"], next_used, next_mask)
                if arrival < distance.get(next_state, float("inf")):
                    distance[next_state] = arrival
                    heapq.heappush(queue, (arrival, edge["v"], next_used, next_mask))
    return {"arrival": None}


SOLVERS = {
    "component_01": _build_ledger(True, True),
    "component_02": _build_ledger(False, False),
    "component_03": _build_ledger(True, False),
    "component_04": _build_ledger(False, True),
    "component_05": _build_ledger(True, True),
    "component_06": _dependency_solver,
    "component_07": _quota_intervals,
    "component_08": _temporal_routes,
}
